func setRequestPath(r *http.Request, path string) error {
	escaped := strings.TrimRight(r.URL.EscapedPath(), "/") + "/" + strings.TrimLeft(path, "/")
	decoded, err := url.PathUnescape(escaped)
	if err != nil {
		return err
	}
	r.URL.Path = decoded
	r.URL.RawPath = escaped
	return nil
}

func setRequestBody(r *http.Request, body []byte) {
	r.Body = io.NopCloser(bytes.NewReader(body))
	r.ContentLength = int64(len(body))
	r.GetBody = func() (io.ReadCloser, error) { return io.NopCloser(bytes.NewReader(body)), nil }
}

func addQueryValue(values url.Values, key string, value interface{}) error {
	v := reflect.ValueOf(value)
	if !v.IsValid() {
		return nil
	}
	if (v.Kind() == reflect.Ptr || v.Kind() == reflect.Interface) && v.IsNil() {
		return nil
	}
	if (v.Kind() == reflect.Slice || v.Kind() == reflect.Array) && v.Type().Elem().Kind() != reflect.Uint8 {
		for i := 0; i < v.Len(); i++ {
			if err := addQueryValue(values, key, v.Index(i).Interface()); err != nil {
				return err
			}
		}
		return nil
	}
	encoded, err := jsoniter.Marshal(value)
	if err != nil {
		return err
	}
	if bytes.Equal(encoded, []byte("null")) {
		return nil
	}
	var text string
	if len(encoded) > 0 && encoded[0] == '"' {
		if err := jsoniter.Unmarshal(encoded, &text); err != nil {
			return err
		}
	} else {
		text = string(encoded)
	}
	values.Add(key, text)
	return nil
}

// HTTPError preserves both the transport status and the server's error body.
type HTTPError struct {
	StatusCode int
	Body       string
}

func (e *HTTPError) Error() string { return fmt.Sprintf("HTTP %d: %s", e.StatusCode, e.Body) }

func decodeHTTPResponse(r *http.Response, target interface{}, enveloped, allowEmpty bool) error {
	body, err := io.ReadAll(r.Body)
	if err != nil {
		return err
	}
	if r.StatusCode < 200 || r.StatusCode >= 300 {
		if len(body) > 8192 {
			body = body[:8192]
		}
		return &HTTPError{StatusCode: r.StatusCode, Body: string(body)}
	}
	if len(bytes.TrimSpace(body)) == 0 {
		if allowEmpty || r.StatusCode == http.StatusNoContent {
			return nil
		}
		return fmt.Errorf("HTTP %d: empty response body", r.StatusCode)
	}
	if enveloped {
		var envelope struct{ Data jsoniter.RawMessage }
		if err := jsoniter.Unmarshal(body, &envelope); err != nil {
			return err
		}
		if len(envelope.Data) == 0 {
			if allowEmpty {
				return nil
			}
			return fmt.Errorf("HTTP response envelope has no data")
		}
		body = envelope.Data
	}
	if err := jsoniter.Unmarshal(body, target); err != nil {
		return fmt.Errorf("decode HTTP response: %w", err)
	}
	return nil
}
